(()=>{if(matchMedia('(prefers-reduced-motion: reduce)').matches)return;const source=document.querySelector('.hero h1'),target=document.querySelector('.landing-title'),hero=document.querySelector('.hero');if(!source||!target)return;function split(node){for(const child of [...node.childNodes]){if(child.nodeType===3){const fragment=document.createDocumentFragment();for(const ch of child.textContent){if(/\s/.test(ch))fragment.append(document.createTextNode(ch));else{const span=document.createElement('span');span.className='flight-letter';span.textContent=ch;fragment.append(span)}}child.replaceWith(fragment)}else if(child.nodeType===1)split(child)}}split(source);split(target);const from=[...source.querySelectorAll('.flight-letter')],to=[...target.querySelectorAll('.flight-letter')],canvas=document.createElement('canvas');canvas.className='letter-flight-layer';canvas.setAttribute('aria-hidden','true');document.body.append(canvas);const c=canvas.getContext('2d');let metrics=[],queued=false;const clamp=x=>Math.max(0,Math.min(1,x));function style(el){const cs=getComputedStyle(el);return {size:parseFloat(cs.fontSize),family:cs.fontFamily,weight:cs.fontWeight,italic:cs.fontStyle,color:cs.color}}function measure(){const ratio=Math.min(devicePixelRatio||1,2);canvas.width=Math.round(innerWidth*ratio);canvas.height=Math.round(innerHeight*ratio);c.setTransform(ratio,0,0,ratio,0,0);metrics=to.map((el,i)=>{const index=Math.floor(i*from.length/to.length);return {from:from[index],to:el,a:style(from[index]),b:style(el),i,duplicates:to.filter((_,j)=>Math.floor(j*from.length/to.length)===index).length}});queue()}
function glyph(ch,font,x,y,angle,alpha,color){if(alpha<.005)return;c.save();c.translate(x,y);c.rotate(angle);c.globalAlpha=alpha;c.fillStyle=color;c.font=font;c.textAlign='center';c.textBaseline='middle';c.fillText(ch,0,0);c.restore()}
function draw(){queued=false;c.clearRect(0,0,innerWidth,innerHeight);const travel=Math.max(1,hero.offsetHeight-innerHeight),start=hero.offsetTop+travel*.04,end=hero.offsetTop+travel+innerHeight*.72,t=clamp((scrollY-start)/(end-start));source.style.opacity=t>0?'0':'';target.style.opacity=t<1?'0':'';if(t<=0||t>=1)return;for(const m of metrics){const r=m.from.getBoundingClientRect(),q=m.to.getBoundingClientRect(),delay=(m.i%7)*.012,p=clamp((t-delay)/(1-delay)),ease=p*p*(3-2*p),arch=Math.sin(p*Math.PI),seed=Math.sin(m.i*13.37);const x=(r.left+r.width/2)*(1-ease)+(q.left+q.width/2)*ease+seed*arch*Math.min(100,innerWidth*.08);const y=(r.top+r.height*.51)*(1-ease)+(q.top+q.height*.51)*ease+arch*(70+(m.i%5)*18);const rotation=arch*seed*.85,size=m.a.size+(m.b.size-m.a.size)*ease,blend=clamp((p-.32)/.36);const fontA=`${m.a.italic} ${m.a.weight} ${size}px ${m.a.family}`,fontB=`${m.b.italic} ${m.b.weight} ${size}px ${m.b.family}`;glyph(m.from.textContent,fontA,x,y,rotation,(1-blend)/m.duplicates,m.a.color);glyph(m.to.textContent,fontB,x,y,rotation,blend,m.b.color)}}function queue(){if(!queued){queued=true;requestAnimationFrame(draw)}}addEventListener('scroll',queue,{passive:true});addEventListener('resize',measure);addEventListener('load',measure);document.fonts.ready.then(measure);measure()})();
